class USBSSP_addr_map_type extends uvm_reg_block;

  rand drd_register_block_type drd_register_block;
  rand asf_register_block_type asf_register_block;
  rand ddusb_register_block_type ddusb_register_block;
  rand usbssp_dev_register_block_type usbssp_dev_register_block;
  rand usbssp_host_register_block_type usbssp_host_register_block;
  rand ddusb_er_register_block_type ddusb_er_register_block;

  virtual function void build();

    // Now create all registers

    drd_register_block = drd_register_block_type::type_id::create("drd_register_block", , get_full_name());
    asf_register_block = asf_register_block_type::type_id::create("asf_register_block", , get_full_name());
    ddusb_register_block = ddusb_register_block_type::type_id::create("ddusb_register_block", , get_full_name());
    usbssp_dev_register_block = usbssp_dev_register_block_type::type_id::create("usbssp_dev_register_block", , get_full_name());
    usbssp_host_register_block = usbssp_host_register_block_type::type_id::create("usbssp_host_register_block", , get_full_name());
    ddusb_er_register_block = ddusb_er_register_block_type::type_id::create("ddusb_er_register_block", , get_full_name());

    // Now build the registers. Set parent and hdl_paths

    drd_register_block.configure(this, "");
    drd_register_block.build();
    asf_register_block.configure(this, "");
    asf_register_block.build();
    ddusb_register_block.configure(this, "");
    ddusb_register_block.build();
    usbssp_dev_register_block.configure(this, "");
    usbssp_dev_register_block.build();
    usbssp_host_register_block.configure(this, "");
    usbssp_host_register_block.build();
    ddusb_er_register_block.configure(this, "");
    ddusb_er_register_block.build();
    // Now define address mappings
    default_map = create_map("default_map", 0, 4, UVM_LITTLE_ENDIAN);
    drd_register_block.lock_model();
    default_map.add_submap(drd_register_block.default_map, `UVM_REG_ADDR_WIDTH'h0);
    asf_register_block.lock_model();
    default_map.add_submap(asf_register_block.default_map, `UVM_REG_ADDR_WIDTH'h100);
    ddusb_register_block.lock_model();
    default_map.add_submap(ddusb_register_block.default_map, `UVM_REG_ADDR_WIDTH'h1000);
    usbssp_dev_register_block.lock_model();
    default_map.add_submap(usbssp_dev_register_block.default_map, `UVM_REG_ADDR_WIDTH'h4000);
    usbssp_host_register_block.lock_model();
    default_map.add_submap(usbssp_host_register_block.default_map, `UVM_REG_ADDR_WIDTH'h8000);
    ddusb_er_register_block.lock_model();
    default_map.add_submap(ddusb_er_register_block.default_map, `UVM_REG_ADDR_WIDTH'hc000);
  endfunction

  `uvm_object_utils(USBSSP_addr_map_type)
  function new(input string name="unnamed-USBSSP_addr_map");
    super.new(name, UVM_NO_COVERAGE);
  endfunction : new

endclass : USBSSP_addr_map_type

//////////////////////////////////////////////////////////////////////////////
// Address_map definition
//////////////////////////////////////////////////////////////////////////////
class USBSSP_addr_map_memory_map_wrapper_type extends uvm_reg_block;

  rand USBSSP_addr_map_type USBSSP_addr_map;

  virtual function void build();
    // Now define address mappings
    default_map = create_map("default_map", 0, 4, UVM_LITTLE_ENDIAN);
    USBSSP_addr_map = USBSSP_addr_map_type::type_id::create("USBSSP_addr_map", , get_full_name());
    USBSSP_addr_map.configure(this, "");
    USBSSP_addr_map.build();
    USBSSP_addr_map.lock_model();
    default_map.add_submap(USBSSP_addr_map.default_map, `UVM_REG_ADDR_WIDTH'h0);
    this.lock_model();
    default_map.set_check_on_read();
  endfunction
  `uvm_object_utils(USBSSP_addr_map_memory_map_wrapper_type)
  function new(input string name="unnamed-USBSSP_addr_map_memory_map_wrapper_type");
    super.new(name, UVM_NO_COVERAGE);
  endfunction
endclass : USBSSP_addr_map_memory_map_wrapper_type

